
/* Run this section of the script as sys or system on the PDB .
 This section will create a new user json_orders with the required privileges to run the other scripts in this repository. 
 It will also enable ORDS for the user (optional), just in case you want to use the Oracle API for MongoDB to access the JSON collection.
The user will be created with a password of DB23ee###12345. You can change this password in the script if you wish.
*/

DROP USER IF EXISTS json_orders CASCADE;
CREATE USER json_orders IDENTIFIED BY DB23ee###12345;
 

GRANT CONNECT, RESOURCE, SODA_APP, DB_DEVELOPER_ROLE TO json_orders;
CREATE OR REPLACE DIRECTORY po_dir as '/home/oracle';
GRANT READ, WRITE ON DIRECTORY po_dir TO json_orders; 
 


--   Enable ORDS (Optional)
BEGIN
  ords_admin.enable_schema(
    p_enabled             => TRUE,
    p_schema              => 'json_orders',
    p_url_mapping_pattern => 'json_orders'
  );
  COMMIT;
END;
/

-- run this section as json_orders on the PDB.  
-- create PurchaseOrders collection table and load data from object storage

DROP TABLE purchaseorders_ext;
DROP TABLE purchaseorders CASCADE CONSTRAINTS PURGE;

CREATE TABLE purchaseorders_ext (
  data JSON
)
ORGANIZATION EXTERNAL (
  TYPE ORACLE_BIGDATA
  DEFAULT DIRECTORY po_dir
  ACCESS PARAMETERS (
    com.oracle.bigdata.fileformat = jsondoc 
  )
  LOCATION (po_dir:'purchaseorders.dmp')
)
PARALLEL
REJECT LIMIT UNLIMITED;

select count(*) from purchaseorders_ext;

/* 10,000 */


-- Creating a collection table to hold the JSON documents.   

DROP TABLE purchaseorders CASCADE CONSTRAINTS PURGE;
CREATE JSON COLLECTION TABLE purchaseorders;

INSERT INTO purchaseorders
SELECT *
FROM purchaseorders_ext;
commit;

SELECT count(*) AS document_count
FROM purchaseorders;
/* 10,000 */

-- Creating an Oracle Table with a JSON Column

DROP TABLE IF EXISTS j_purchaseorders CASCADE CONSTRAINTS;
CREATE TABLE j_purchaseorders 
  (id          VARCHAR2 (32) NOT NULL PRIMARY KEY,
   date_loaded TIMESTAMP (6) WITH TIME ZONE,
   po_document JSON);

-- Inserting a JSON document into the Hybrid table
INSERT INTO j_purchaseorders 
  SELECT SYS_GUID(), SYSTIMESTAMP, DATA 
    FROM purchaseorders;
 SELECT SYS_GUID(),SYSTIMESTAMP,DATA 
    FROM purchaseorders
    FETCH FIRST 5 ROWS ONLY;

